#!/usr/bin/env python3
"""
Attrium Single-Bind ClickGUI Fixer (Fabric 1.21.11)
- Direct GLFW keyboard + mouse polling fallback for the Client tab ClickGUI bind changer
  (works even if another mod/launcher overwrites glfwSetKeyCallback).
- Makes the Client tab ClickGUI bind ONLY open ClickGUI (never close) and disables EVERY
  other ClickGUI opener across src/main/java so the Client tab bind is the ONLY way to open it.
"""
import base64
import os
import re
import sys

FILES_B64 = {
    "attrium/ru/manager/ClientThemeManager.java": "",
    "attrium/ru/manager/FriendManager.java": "",
    "attrium/ru/manager/HudManager.java": "",
    "attrium/ru/screens/GlassClickGuiScreen.java": "",

}


def disable_all_other_clickgui_openers(src_root):
    skip_files = {
        "GlassClickGuiScreen.java",
        "ClientThemeManager.java",
        "HudManager.java",
        "FriendManager.java",
        "KeybindsModule.java",
        "TickPipelineManager.java",
    }
    found = 0
    for root, _, files in os.walk(src_root):
        for fn in files:
            if not fn.endswith(".java") or fn in skip_files:
                continue
            path = os.path.join(root, fn)
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                src = f.read()
            if "GlassClickGuiScreen" not in src:
                continue
            orig = src
            # Disable ANY external setScreen(...GlassClickGuiScreen...) call so ONLY GlassClickGuiScreen's
            # Client-tab bind can open ClickGUI.
            src = re.sub(
                r"([ \t]*)([^;\n]*\.setScreen\s*\([^;\n]*GlassClickGuiScreen[^;\n]*\)\s*;)",
                r"\1/* disabled legacy ClickGUI opener: \2 */",
                src,
            )
            if src != orig:
                with open(path, "w", encoding="utf-8") as f:
                    f.write(src)
                print(f"[DISABLED LEGACY OPENER] {os.path.relpath(path, src_root)}")
                found += 1
    if found == 0:
        print("[INFO] No other external GlassClickGuiScreen openers found.")


def main():
    cwd = os.getcwd()
    src_root = os.path.join(cwd, "src", "main", "java")
    if not os.path.isdir(src_root):
        print(f"[ERROR] Run this script from your project root (missing {src_root}).")
        sys.exit(1)
    for rel_path, b64_data in FILES_B64.items():
        out_path = os.path.join(src_root, *rel_path.split("/"))
        os.makedirs(os.path.dirname(out_path), exist_ok=True)
        with open(out_path, "wb") as f:
            f.write(base64.b64decode(b64_data))
        print(f"[OK] Wrote {rel_path}")
    disable_all_other_clickgui_openers(src_root)
    print("\nDone! Run: ./gradlew build --no-daemon")


if __name__ == "__main__":
    main()